  border-top: 4px solid var(--primary);
  border-radius: 12px;
  height: 100%;
  min-height: 170px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  box-shadow: 0 4px 16px rgba(12, 30, 51, 0.05);
}

.card-service:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 28px rgba(2, 132, 199, 0.16);
}

.card-service h6 {
  color: var(--dark);
  font-size: 1.05rem;
  min-height: 2.6rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5rem;
}

.card-service p {
  color: var(--text-muted);
  line-height: 1.5;
}

/* Testimonials */
.section-testimonial {
  background-color: var(--bg-surface);
  position: relative;
}

.testimonial-card {
  background-color: var(--bg-app);
  border: 1px solid var(--card-border);
  box-shadow: 0 6px 20px rgba(12, 30, 51, 0.04);
}

.testimonial-card p.fs-4 {
  color: var(--dark);
  font-family: var(--font-headings);
  line-height: 1.5;
  font-weight: 500;
}

